import type { SlotState } from '#shared/domain/dayOverview'
import type { Qualification, StaffingMethod } from '#shared/domain/staffing/types'
import type { GroupColor, MeetingKind, StaffingEstimateReason } from '#shared/types/api'

const days = (count: number) => (count === 1 ? '1 Tag' : `${count.toLocaleString('de-DE')} Tage`)
/** „Zusatztag nur für dieses Jahr“: „1 Zusatztag“, „1,5 Zusatztage“. */
const extraDayCount = (count: number) => (count === 1 ? '1 Zusatztag' : `${count.toLocaleString('de-DE')} Zusatztage`)
/** Leave days of a request; 24 and 31 December may count half, so „7,5 Arbeitstage“. */
const workdays = (count: number) => (count === 1 ? '1 Arbeitstag' : `${count.toLocaleString('de-DE')} Arbeitstage`)
/** A pickup person typed by hand ("Andere Person"), as lists, print and history show it. */
const notRegistered = (name: string) => `${name} (nicht hinterlegt)`
const confirmedWith = (text: string) => `Rücksprache mit ${text}`
/** Days of booked leave kept as another absence (approving a request, „Urlaub eintragen“). */
const keptAbsencesNote = (count: number, kind: string) => (count === 1
  ? `1 Tag mit einer anderen Abwesenheit (Krank, Fortbildung, Urlaub o. Ä.) blieb unverändert und zählt nicht als ${kind}.`
  : `${count} Tage mit einer anderen Abwesenheit (Krank, Fortbildung, Urlaub o. Ä.) blieben unverändert und zählen nicht als ${kind}.`)
/** „an 1 Tag“ / „an 5 Tagen“ (plan days, whatever they count in the leave account). */
const onDays = (count: number) => (count === 1 ? 'an 1 Tag' : `an ${count} Tagen`)
/** The Träger's templates for all facilities that leave a category (deleted or renamed) for „Vom Träger“. */
const providerMoves = (count: number) => (count === 1
  ? 'Die 1 Vorlage des Trägers darin steht danach unter „Vom Träger“ – sichtbar für alle, für die der Träger sie freigegeben hat.'
  : `Die ${count} Vorlagen des Trägers darin stehen danach unter „Vom Träger“ – sichtbar für alle, für die der Träger sie freigegeben hat.`)
/** Deleting or renaming a subcategory: the Träger's templates in it then show directly in its category. */
const generalMoves = (count: number) => (count === 1
  ? 'Die 1 Vorlage des Trägers darin steht danach direkt in der Kategorie („Allgemein“).'
  : `Die ${count} Vorlagen des Trägers darin stehen danach direkt in der Kategorie („Allgemein“).`)
/** Jugendarbeitsschutz without a birth year: in the plan's hints (with the name) and on the employee page. */
const YOUTH_BIRTH_YEAR_MISSING = 'Geburtsjahr fehlt – Jugendarbeitsschutz kann nicht geprüft werden'
/** A birth year without a birthday in the year of the 18th birthday (the same places). */
const YOUTH_BIRTHDAY_MISSING = 'Geburtstag fehlt – Jugendarbeitsschutz kann nicht sicher geprüft werden'
/** Format errors of the personnel file (shared/domain/personnel.ts): `personnel.invalid` and, as API errors, `errors`. */
const personnelInvalid = {
  iban_invalid: 'Die IBAN stimmt nicht. Bitte prüfe sie noch einmal (z. B. DE89 3704 0044 0532 0130 00).',
  tax_id_invalid: 'Die Steuer-ID stimmt nicht. Sie hat 11 Ziffern; bitte prüfe sie noch einmal.',
  sv_number_invalid: 'Die Sozialversicherungsnummer stimmt nicht. Sie hat 12 Zeichen: 8 Ziffern, einen Buchstaben und 3 Ziffern (z. B. 15 070649 C 103).',
  tax_class_invalid: 'Die Steuerklasse muss zwischen 1 und 6 liegen.',
  email_invalid: 'Bitte gib eine gültige E-Mail-Adresse an (z. B. name@beispiel.de).',
  postal_code_invalid: 'Die Postleitzahl hat 5 Ziffern.',
  disability_degree_invalid: 'Der Grad der Behinderung liegt zwischen 20 und 100, in Zehnerschritten.',
  birth_year_invalid: 'Bitte gib ein gültiges Geburtsjahr an, das zum Geburtstag passt.',
}

