      protectedMiscarriage: (name: string) => `${name}: Schutzfrist nach der Fehlgeburt (§ 3 Abs. 5 MuSchG)`,
      ban: (name: string) => `${name}: Dienst trotz Beschäftigungsverbot (§§ 13, 16 MuSchG)`,
